static order_state step(order_state st, const event *ev, sqlite3 *db) {
    switch (st) {
    case AWAITING_PAYMENT:
        if (ev->kind != PAYMENT_OK) break;        /* ignore stale replies */
        if (enqueue(db, ev->corr_id, "reserve") == 0)
            return AWAITING_STOCK;
        return COMPENSATING;                      /* reserve rejected */
    case AWAITING_STOCK:
        if (ev->kind == RESERVE_OK) return DONE;
        break;
    case COMPENSATING:
        release_credit(db, ev->corr_id);
        return FAILED;
    }
    return st;
}

